# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs, factor=3):
    return [v * factor for v in xs]

# region: sift
def sift(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(gather(sift(fold(shape(raw)))))

